pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/token/common/ERC2981.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title AINFT Marketplace
 * @notice A combined ERC721 NFT and marketplace contract for AI agents.
 * It allows minting of new agent NFTs, setting royalties, and provides
 * a decentralized, non-custodial marketplace for listing, buying, and selling them.
 * This contract adheres to OpenZeppelin v4.9.x standards.
 */
contract AINFT is ERC721Enumerable, ERC721URIStorage, ERC2981, Ownable, ReentrancyGuard {
    using Counters for Counters.Counter;
    Counters.Counter private _tokenIdCounter;

    // --- State ---

    struct Listing {
        address seller;
        uint256 price;
    }

    mapping(uint256 => Listing) private _listings;

    uint256 public marketplaceFeeBps;
    address payable public feeRecipient;

    uint256 public constant MAX_FEE_BPS = 1000; // 10% maximum fee

    // --- Errors ---

    error NotListed();
    error AlreadyListed();
    error NotTokenOwner();
    error NotApproved();
    error PriceMustBePositive();
    error InsufficientPayment();
    error FeeTooHigh();
    error ZeroAddress();
    error TransferFailed();

    // --- Events ---

    event AgentListed(uint256 indexed tokenId, address indexed seller, uint256 price);
    event AgentSold(uint256 indexed tokenId, address indexed seller, address indexed buyer, uint256 price);
    event AgentDelisted(uint256 indexed tokenId);

    // --- Constructor ---

    /**
     * @notice Initializes the contract, setting default marketplace fees.
     * The contract name and symbol are hard-coded in overridden functions.
     * The deployer of the contract becomes the owner.
     */
    constructor() ERC721("AI Agent NFT", "AINFT") {
        marketplaceFeeBps = 250; // Default to 2.5%
        feeRecipient = payable(msg.sender);
    }

    // --- OpenZeppelin Hook and Function Overrides ---

    /**
     * @dev See {ERC721-_beforeTokenTransfer}.
     * This hook automatically delists an agent if it is transferred,
     * ensuring marketplace listings remain valid.
     */
    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 firstTokenId,
        uint256 batchSize
    ) internal override(ERC721, ERC721Enumerable) {
        super._beforeTokenTransfer(from, to, firstTokenId, batchSize);

        if (from != address(0)) {
            for (uint256 i = 0; i < batchSize; ++i) {
                uint256 tokenId = firstTokenId + i;
                Listing memory listing = _listings[tokenId];
                if (listing.price > 0 && listing.seller == from) {
                    delete _listings[tokenId];
                    emit AgentDelisted(tokenId);
                }
            }
        }
    }

    /**
     * @dev See {ERC721URIStorage-_burn}.
     * Ensures a token is delisted from the marketplace if it's burned.
     */
    function _burn(uint256 tokenId) internal override(ERC721, ERC721URIStorage) {
        if (_listings[tokenId].price > 0) {
            delete _listings[tokenId];
            emit AgentDelisted(tokenId);
        }
        super._burn(tokenId);
    }

    /**
     * @dev See {ERC721URIStorage-tokenURI}.
     */
    function tokenURI(uint256 tokenId)
        public
        view
        override(ERC721, ERC721URIStorage)
        returns (string memory)
    {
        return super.tokenURI(tokenId);
    }

    /**
     * @dev See {IERC165-supportsInterface}.
     */
    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721Enumerable, ERC721URIStorage, ERC2981)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    // --- Minting ---

    /**
     * @notice Mints a new AI Agent NFT.
     * @dev Can only be called by the contract owner.
     * @param to The address to receive the new NFT.
     * @param uri The metadata URI for the agent.
     * @param royaltyRecipient The address to receive on-chain royalties.
     * @param royaltyFeeNumerator The royalty fee in basis points (e.g., 500 for 5%).
     */
    function safeMint(address to, string memory uri, address royaltyRecipient, uint96 royaltyFeeNumerator) public onlyOwner {
        if (to == address(0) || royaltyRecipient == address(0)) revert ZeroAddress();

        _tokenIdCounter.increment();
        uint256 tokenId = _tokenIdCounter.current();

        _safeMint(to, tokenId);
        _setTokenURI(tokenId, uri);
        _setTokenRoyalty(tokenId, royaltyRecipient, royaltyFeeNumerator);
    }

    // --- Marketplace ---

    /**
     * @notice Lists an AI Agent NFT for sale on the marketplace.
     * @dev The caller must be the owner of the token and must have approved the
     * marketplace contract to transfer it.
     * @param tokenId The ID of the token to list.
     * @param price The selling price in wei.
     */
    function listAgent(uint256 tokenId, uint256 price) public {
        if (price == 0) revert PriceMustBePositive();
        address tokenOwner = ownerOf(tokenId);
        if (tokenOwner != msg.sender) revert NotTokenOwner();
        if (_listings[tokenId].price > 0) revert AlreadyListed();

        if (getApproved(tokenId) != address(this) && !isApprovedForAll(tokenOwner, address(this))) {
            revert NotApproved();
        }

        _listings[tokenId] = Listing(msg.sender, price);
        emit AgentListed(tokenId, msg.sender, price);
    }

    /**
     * @notice Removes an NFT from the marketplace.
     * @dev Only the original seller can delist their agent.
     * @param tokenId The ID of the token to delist.
     */
    function delistAgent(uint256 tokenId) public {
        Listing memory listing = _listings[tokenId];
        if (listing.price == 0) revert NotListed();
        if (listing.seller != msg.sender) revert NotTokenOwner();

        delete _listings[tokenId];
        emit AgentDelisted(tokenId);
    }

    /**
     * @notice Buys a listed AI Agent NFT.
     * @dev The transaction must include a value greater than or equal to the listing price.
     * Overpayment will be refunded.
     * @param tokenId The ID of the token to purchase.
     */
    function buyAgent(uint256 tokenId) public payable nonReentrant {
        Listing memory listing = _listings[tokenId];
        if (listing.price == 0) revert NotListed();
        if (msg.value < listing.price) revert InsufficientPayment();

        address seller = listing.seller;
        if (ownerOf(tokenId) != seller) revert NotListed();

        delete _listings[tokenId];

        (address royaltyRecipient, uint256 royaltyAmount) = royaltyInfo(tokenId, listing.price);
        uint256 feeAmount = (listing.price * marketplaceFeeBps) / 10000;

        uint256 totalDeductions = feeAmount + royaltyAmount;
        if (totalDeductions > listing.price) {
            // Safeguard against misconfigured fees > 100%
            revert("AINFT: Fees exceed sale price");
        }
        uint256 sellerProceeds = listing.price - totalDeductions;

        _safePay(payable(seller), sellerProceeds);
        if (feeAmount > 0) _safePay(feeRecipient, feeAmount);
        if (royaltyAmount > 0) _safePay(payable(royaltyRecipient), royaltyAmount);

        _safeTransfer(seller, msg.sender, tokenId, "");

        if (msg.value > listing.price) {
            _safePay(payable(msg.sender), msg.value - listing.price);
        }

        emit AgentSold(tokenId, seller, msg.sender, listing.price);
    }

    /**
     * @notice Gets the listing details for a specific token.
     * @param tokenId The ID of the token.
     * @return A Listing struct containing the seller and price.
     */
    function getListing(uint256 tokenId) public view returns (Listing memory) {
        return _listings[tokenId];
    }

    // --- Admin Functions ---

    /**
     * @notice Updates the marketplace fee.
     * @dev Can only be called by the owner. Fee cannot exceed `MAX_FEE_BPS`.
     * @param _feeBps The new fee in basis points.
     */
    function setMarketplaceFee(uint256 _feeBps) public onlyOwner {
        if (_feeBps > MAX_FEE_BPS) revert FeeTooHigh();
        marketplaceFeeBps = _feeBps;
    }

    /**
     * @notice Updates the address that receives marketplace fees.
     * @dev Can only be called by the owner.
     * @param _recipient The new fee recipient address.
     */
    function setFeeRecipient(address payable _recipient) public onlyOwner {
        if (_recipient == address(0)) revert ZeroAddress();
        feeRecipient = _recipient;
    }

    /**
     * @notice Allows the owner to withdraw any ETH accidentally sent to the contract.
     */
    function withdraw() public onlyOwner {
        uint256 balance = address(this).balance;
        if (balance > 0) {
            _safePay(payable(owner()), balance);
        }
    }

    // --- Internal Helpers ---

    /**
     * @dev Internal function to safely send ETH.
     */
    function _safePay(address payable to, uint256 value) internal {
        if (value == 0) return;
        (bool success, ) = to.call{value: value}("");
        if (!success) revert TransferFailed();
    }
}

